#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<int> a(N);
    for (int &x : a) cin >> x;

    int answer = 1;

    for (int x = 1; x <= N; ++x) {
        for (int y = x + 1; y <= N; ++y) {
            int dpX = 0, dpY = 0;

            for (int v : a) {
                if (v == x) {
                    dpX = max(dpX, dpY + 1);
                } else if (v == y) {
                    dpY = max(dpY, dpX + 1);
                }
            }

            answer = max(answer, max(dpX, dpY));
        }
    }

    cout << answer << '\n';
    return 0;
}
